با توجه به اینکه، ABCD یک متوازی‌الاضلاع است. AC و BD دو قطر آن هستند. باید بردارهای \vec{AB} و \vec{AC} را بر حسب \vec{AD} و \vec{BD} بیان کرده و نشان دهیم که،
\vec{AC} + \vec{BD} = 2\vec{BC} \text{ و } \vec{AC} - \vec{BD} = 2\vec{AB}.

\text{در مثلث } \Delta ABD،
\vec{AD} = \vec{AB} + \vec{BD} \text{ [قانون مثلث]}
\therefore \vec{AB} = \vec{AD} - \vec{BD} \text{.............(i)}
\text{دوباره در مثلث ACD، } \vec{AC} = \vec{AD} + \vec{DC} \text{[قانون مثلث]}
\text{[از آنجایی که، ABCD متوازی‌الاضلاع است، پس } \vec{DC} = \vec{AB}]
= \vec{AD} + \vec{AD} - \vec{BD} [\because \vec{AB} = \vec{AD} - \vec{BD}]
\therefore \vec{AC} = 2\vec{AD} - \vec{BD} \text{.............(ii)}
\text{حالا، } \vec{AC} + \vec{BD} = 2\vec{AD} - \vec{BD} + \vec{BD}
\text{[با اضافه کردن } \vec{BD} \text{ به دو طرف (ii)]}
= 2 \vec{AD}
\therefore \vec{AC} + \vec{BD} = 2 \vec{BC} \text{.............(iii)}
\text{[از آنجایی که، ABCD متوازی‌الاضلاع است، پس } \vec{AD} = \vec{BC}]
\text{دوباره، } \vec{AC} - \vec{BD} = (2\vec{AD} - \vec{BD}) - \vec{BD} \text{ [با استفاده از (ii)]}
= 2\vec{AD} - 2 \vec{BD} = 2 (\vec{AD} - \vec{BD})
= 2\vec{AB} \text{ [با استفاده از (i)]}
\therefore \vec{AC} - \vec{BD} = 2\vec{AB} \text{.............(iv)}
\text{حالا، از معادلات (i)، (ii)، (iii) و (iv) به دست می‌آوریم،}
\vec{AB} = \vec{AD} - \vec{BD}
\vec{AC} = 2\vec{AD} - \vec{BD}
\vec{AC} + \vec{BD} = 2\vec{BC} \text{ و } \vec{AC} - \vec{BD} = 2\vec{AB} \text{ (اثبات شد)}

